-- đã chạy 
--Điều kiện: 01..10, đặc biệt clinic.services và medical.medicalVisits.
-- Xét nghiệm/chẩn đoán nhập thủ công, không tích hợp thiết bị.
BEGIN;
CREATE TABLE IF NOT EXISTS medical."diagnosticOrders" (
    "diagnosticOrderID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "visitID" BIGINT NOT NULL REFERENCES medical."medicalVisits"("visitID") ON DELETE RESTRICT,
    "serviceID" BIGINT NOT NULL REFERENCES clinic."services"("serviceID") ON DELETE RESTRICT,
    "orderedByVeterinarianID" BIGINT NOT NULL REFERENCES clinic."veterinarians"("veterinarianID") ON DELETE RESTRICT,
    "performedByStaffID" BIGINT REFERENCES clinic."clinicStaff"("staffID") ON DELETE RESTRICT,
    "status" VARCHAR(20) NOT NULL DEFAULT 'PENDING'
        CHECK ("status" IN ('PENDING', 'PROCESSING', 'COMPLETED', 'CANCELLED')),
    "orderedAt" TIMESTAMPTZ NOT NULL DEFAULT now(),
    "performedAt" TIMESTAMPTZ,
    "resultSummary" TEXT,
    "conclusion" TEXT,
    "fileUrl" TEXT,
    "note" TEXT,
    CONSTRAINT "ckDiagnosticPerformedTime" CHECK ("performedAt" IS NULL OR "performedAt" >= "orderedAt"),
    CONSTRAINT "ckDiagnosticCompleted" CHECK (
        "status" <> 'COMPLETED' OR (
            "performedAt" IS NOT NULL AND "performedByStaffID" IS NOT NULL
            AND "resultSummary" IS NOT NULL AND length(trim("resultSummary")) > 0
            AND "conclusion" IS NOT NULL AND length(trim("conclusion")) > 0
        )
    )
);
CREATE TABLE IF NOT EXISTS medical."diagnosticResultItems" (
    "resultItemID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "diagnosticOrderID" BIGINT NOT NULL REFERENCES medical."diagnosticOrders"("diagnosticOrderID") ON DELETE RESTRICT,
    "parameterName" VARCHAR(150) NOT NULL CHECK (length(trim("parameterName")) > 0),
    "valueText" TEXT,
    "valueNumeric" NUMERIC(18,6),
    "unit" VARCHAR(50),
    "referenceRange" VARCHAR(150),
    -- Mở theo thiết kế: NORMAL, HIGH, LOW... backend chuẩn hóa giá trị hiển thị.
    "abnormalFlag" VARCHAR(30),
    "note" TEXT,
    CONSTRAINT "ckDiagnosticResultValue" CHECK (
        "valueNumeric" IS NOT NULL OR ("valueText" IS NOT NULL AND length(trim("valueText")) > 0)
    )
);
CREATE INDEX IF NOT EXISTS "idxDiagnosticOrdersVisit" ON medical."diagnosticOrders" ("visitID");
CREATE INDEX IF NOT EXISTS "idxDiagnosticOrdersService" ON medical."diagnosticOrders" ("serviceID");
CREATE INDEX IF NOT EXISTS "idxDiagnosticOrdersOrderedBy" ON medical."diagnosticOrders" ("orderedByVeterinarianID");
CREATE INDEX IF NOT EXISTS "idxDiagnosticOrdersPerformerStatus" ON medical."diagnosticOrders" ("performedByStaffID", "status");
CREATE INDEX IF NOT EXISTS "idxDiagnosticResultItemsOrder" ON medical."diagnosticResultItems" ("diagnosticOrderID");
COMMENT ON COLUMN medical."diagnosticOrders"."fileUrl" IS
    'Khóa/đường dẫn nội bộ đến tệp kết quả; backend phục vụ qua endpoint có phân quyền, không mặc định URL static công khai.';
-- Backend kiểm tra dịch vụ active, quyền bác sĩ/người thực hiện và không sửa ca/chỉ định đã khóa.
COMMIT;
